import{_ as e,c as r,o as t,a4 as n}from"./chunks/framework.Cn-pVit8.js";const a="/assets/how-to-dynamic-routes.DBIXBRRQ.png",m=JSON.parse('{"title":"渲染方式","description":"","frontmatter":{},"headers":[],"relativePath":"React/nextjs.md","filePath":"React/nextjs.md","lastUpdated":1713170519000}'),s={name:"React/nextjs.md"},o=n('<blockquote><p><a href="https://nextjs.org/" target="_blank" rel="noreferrer">https://nextjs.org/</a></p></blockquote><p>serverless function？</p><blockquote><p>目录</p></blockquote><p>├─public ├─style ├─components │ ├─layout │ └─comp2 │─pages ├─_app.j └─page-1 └─page-2</p><h1 id="渲染方式" tabindex="-1">渲染方式 <a class="header-anchor" href="#渲染方式" aria-label="Permalink to &quot;渲染方式&quot;">​</a></h1><h2 id="pre-rendering" tabindex="-1">Pre-rendering <a class="header-anchor" href="#pre-rendering" aria-label="Permalink to &quot;Pre-rendering&quot;">​</a></h2><p>默认所有的页面都会被 pre-rendering，Next.js 有两种 pre-rendering 形式，他们的区别在于生成 HTML 的时机。</p><p>Next.js has two forms of pre-rendering: <a href="https://www.nextjs.cn/docs/basic-features/pages#static-generation-recommended" target="_blank" rel="noreferrer"><strong>Static Generation</strong></a> and <a href="https://www.nextjs.cn/docs/basic-features/pages#server-side-rendering" target="_blank" rel="noreferrer"><strong>Server-side Rendering</strong></a>.</p><ol><li><a href="https://www.nextjs.cn/docs/basic-features/pages#static-generation-recommended" target="_blank" rel="noreferrer"><strong>Static Generation</strong></a> is the pre-rendering method that generates the HTML at <strong>build time</strong>. The pre-rendered HTML is then <em>reused</em> on each request.</li></ol><p>在用户请求之前生成页面，不涉及动态数据，无法使用仅在请求期间可用的数据，例如查询参数或HTTP标头。</p><p><strong>API</strong>：getStaticProps，只在服务端执行</p><p>In development mode (when you run <code>npm run dev</code> or <code>yarn dev</code>), every page is <a href="https://www.nextjs.cn/docs/basic-features/pages#pre-rendering" target="_blank" rel="noreferrer">pre-rendered</a> on each request — even for pages that use <a href="https://www.nextjs.cn/docs/basic-features/pages#static-generation-recommended" target="_blank" rel="noreferrer">Static Generation</a>.</p><p><a href="https://www.nextjs.cn/docs/basic-features/data-fetching#getstaticprops-static-generation" target="_blank" rel="noreferrer"><code>getStaticProps</code></a> runs <strong>only on the server-side</strong>. It will never run on the client-side. It won’t even be included in the JS bundle for the browser.</p><ol start="2"><li><a href="https://www.nextjs.cn/docs/basic-features/pages#server-side-rendering" target="_blank" rel="noreferrer"><strong>Server-side Rendering</strong></a> is the pre-rendering method that generates the HTML on <strong>each request</strong>.</li></ol><p>每次请求时，获取数据，然后生成 HTML 文件</p><p><strong>API</strong>：getServerSideProps，只在服务端执行</p><p>Serve-Side Rendering 的 TTFB 比 Static Generation 慢</p><p>Q：如何判断一个页面是静态生成的页面？</p><p>A：如果没有阻塞数据要求，Next.js 就会自动判断页面是静态的。这意味着页面中没有 getServerSideProps 和 getInitialProps。</p><blockquote><p>根据动态路由生成静态 HTML</p></blockquote><img src="'+a+'" alt="how-to-dynamic-routes" style="zoom:50%;"><h2 id="client-side-rendering" tabindex="-1">Client-side Rendering <a class="header-anchor" href="#client-side-rendering" aria-label="Permalink to &quot;Client-side Rendering&quot;">​</a></h2><p>Client-side 请求数据推荐使用 Nextjs 内置的 <code>swr</code> hook</p><h1 id="incremental-static-regeneration-isr" tabindex="-1">Incremental Static Regeneration (ISR) <a class="header-anchor" href="#incremental-static-regeneration-isr" aria-label="Permalink to &quot;Incremental Static Regeneration (ISR)&quot;">​</a></h1><p>增量静态再生</p>',25),i=[o];function c(d,p,l,g,h,u){return t(),r("div",null,i)}const _=e(s,[["render",c]]);export{m as __pageData,_ as default};
